#!/usr/bin/env node
/**
 * VELTRAXX 2.0 - Staging Database Restoration & Round-Trip Verification Utility
 * Safely restores a JSON backup generated by scripts/backup_supabase.mjs into an
 * ISOLATED STAGING Supabase project and verifies restored row counts match 100%.
 *
 * SAFETY GUARD: Refuses to run against known production ref `krkiwilhwppqauyhwlcw`.
 *
 * Usage:
 *   node scripts/restore_supabase.mjs backups/veltraxx_backup_xxx.json --confirm-staging
 */

import fs from 'node:fs';
import path from 'node:path';

const PRODUCTION_REF = 'krkiwilhwppqauyhwlcw';
const SUPABASE_URL = (process.env.SUPABASE_URL || process.env.STAGING_SUPABASE_URL || '').replace(/\/$/, '');
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.STAGING_SUPABASE_SERVICE_ROLE_KEY || '';

const args = process.argv.slice(2);
const backupPath = args.find((a) => !a.startsWith('--'));
const confirmedStaging = args.includes('--confirm-staging');

if (!confirmedStaging || !backupPath) {
  console.error('Usage: node scripts/restore_supabase.mjs <backup.json> --confirm-staging');
  process.exit(1);
}

if (!SUPABASE_URL || !SERVICE_KEY) {
  console.error('ERROR: Target STAGING SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY must be set in environment.');
  process.exit(1);
}

if (SUPABASE_URL.includes(PRODUCTION_REF)) {
  console.error('BLOCKED: Refusing to restore backup into production Supabase project.');
  process.exit(2);
}

const RESTORE_ORDER = [
  { table: 'event_state', conflict: 'id' },
  { table: 'coordinator_allowlist', conflict: 'email' },
  { table: 'teams', conflict: 'team_id' },
  { table: 'members', conflict: 'id' },
  { table: 'ppt_submission_attempts', conflict: 'id' },
  { table: 'ppt_submissions', conflict: 'id' },
  { table: 'sync_jobs', conflict: 'id' },
  { table: 'user_reports', conflict: 'id' }
];

async function upsertRows(table, conflict, rows) {
  if (!Array.isArray(rows) || rows.length === 0) {
    return { restored: 0 };
  }
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}?on_conflict=${conflict}`, {
    method: 'POST',
    headers: {
      apikey: SERVICE_KEY,
      Authorization: `Bearer ${SERVICE_KEY}`,
      'Content-Type': 'application/json',
      Prefer: 'resolution=merge-duplicates,return=minimal'
    },
    body: JSON.stringify(rows)
  });

  if (res.status === 404) {
    return { skipped: true, restored: 0 };
  }
  if (!res.ok) {
    throw new Error(`Restore failed for ${table}: HTTP ${res.status} ${await res.text()}`);
  }
  return { restored: rows.length };
}

async function countTable(table) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${table}?select=count`, {
    headers: {
      apikey: SERVICE_KEY,
      Authorization: `Bearer ${SERVICE_KEY}`,
      Prefer: 'count=exact'
    }
  });
  if (res.status === 404) return null;
  if (!res.ok) throw new Error(`Count failed for ${table}: HTTP ${res.status}`);
  const range = res.headers.get('content-range') || '';
  const total = range.split('/')[1];
  return total ? Number(total) : (await res.json()).length;
}

async function main() {
  const resolved = path.resolve(process.cwd(), backupPath);
  const archive = JSON.parse(fs.readFileSync(resolved, 'utf8'));

  console.log(`[RESTORE] Source archive created at: ${archive.created_at}`);
  for (const { table, conflict } of RESTORE_ORDER) {
    const entry = archive.tables?.[table];
    if (!entry || !entry.exists) {
      console.log(`[SKIP] ${table}: not present in archive.`);
      continue;
    }
    const r = await upsertRows(table, conflict, entry.rows);
    if (r.skipped) {
      console.log(`[SKIP] ${table}: table absent in target staging schema.`);
      continue;
    }
    const actualCount = await countTable(table);
    console.log(`[RESTORED] ${table}: pushed ${r.restored} rows | staging row count=${actualCount}`);
    if (actualCount !== null && actualCount < entry.rows.length) {
      throw new Error(`Row count verification mismatch on ${table}: expected >= ${entry.rows.length}, got ${actualCount}`);
    }
  }
  console.log('[VERIFIED] Staging restore & row count checks passed.');
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
